import { OtpInput } from '@absoluteui/components/otp-input';

const host = document.querySelector<HTMLElement>('#code');
const form = document.querySelector<HTMLFormElement>('#verify');
if (host && form) {
  const otp = OtpInput.create(host, { label: 'Verification code', name: 'code', required: true, description: 'Enter the code from your authenticator app.' });
  otp.host.addEventListener('aui-complete', () => {
    form.requestSubmit();
  });
}

import { OtpInput } from '@absoluteui/components/otp-input';

const host = document.querySelector<HTMLElement>('#recovery');
